#  PeFLL client: receives hypernetwork-generated head parameters.
#
# Unlike FedRep/FedBABU clients which maintain and train their own
# local heads, PeFLL clients receive personalised head parameters
# generated by the server's hypernetwork each round.  The client's
# role is to:
#   1. Provide a batch of local data for embedding computation
#   2. Receive generated head parameters from the server
#   3. Evaluate the personalised model (shared base + generated head)
#   4. Compute and return the local loss for server-side backpropagation
#
# The client does not train locally in the traditional sense.  All
# optimisation happens on the server through the hypernetwork.
#
# Adapts from:
#   - PeFLL train.py        : the client-side logic in the training loop
#   - client_base.py        : our WESADClient base class
#

from __future__ import annotations

from collections import OrderedDict

import torch

from ...models.wesad_fl_model import WESADFLModel
from ...utils.fl_config import FLConfig
from ...utils.wesad_fl_dataset import FLClientDataManager
from ..clients.client_base import WESADClient


class PeFLLClient(WESADClient):
    """PeFLL client: receives generated head parameters from the server.

    The client provides data batches for embedding computation and
    evaluates the personalised model.

    Parameters: same as WESADClient
    """

    def __init__(
        self,
        config: FLConfig,
        subject_id: int,
        data_manager: FLClientDataManager,
        global_model: WESADFLModel,
        device: torch.device,
    ):
        super().__init__(config, subject_id, data_manager, global_model, device)

        # PeFLL clients don't use the base class's full-model optimizer
        # for head training, as heads are generated by the server's
        # hypernetwork.  Set to None.
        self.optimizer = None
        self.lr_scheduler = None

        # Base optimizer for FedAvg-style base training.
        # Must be persistent (not recreated each round) to preserve
        # AdamW's adaptive moment estimates across rounds.
        self.base_optimizer = torch.optim.AdamW(
            self.model.base.parameters(),
            lr=self.learning_rate,
            weight_decay=config.weight_decay,
        )

    def get_embedding_batch(self, n_samples: int = 32) -> dict[str, torch.Tensor]:
        """Get a batch of local data for embedding computation.

        The server uses this batch to compute the client's embedding
        via the embedding network.

        Parameters:
        n_samples : int
            Number of samples to include in the embedding batch.
            Smaller batches are faster but noisier.

        Returns:
        dict[str, torch.Tensor]
            signal_name → (n_samples, C, T) tensor, on self.device.
        """
        loader = self.load_train_data(batch_size=n_samples)
        # Get first batch only
        signals, labels = next(iter(loader))
        signals = {k: v.to(self.device) for k, v in signals.items()}
        return signals

    def set_head_parameters(self, head_params: OrderedDict):
        """Load hypernetwork-generated parameters into the head.

        Tthe server generates head parameters from the client's embedding, and
        the client loads them directly.

        Parameters:
        head_params : OrderedDict[str, torch.Tensor]
            Parameter name → tensor, as produced by WESADHyperNet.
            Keys must match model.head's learnable parameter names.
        """
        head_state = self.model.head.state_dict()

        # Validate that all generated parameter names exist in head
        learnable_names = {name for name, _ in self.model.head.named_parameters()}
        for name in head_params:
            if name not in learnable_names:
                raise KeyError(
                    f"Generated parameter '{name}' not found in head's "
                    f"learnable parameters. Available: {sorted(learnable_names)}"
                )

        # Load generated params into state dict
        for name, param in head_params.items():
            head_state[name] = param

        # strict=False because head_state also contains BatchNorm
        # running_mean/running_var/num_batches_tracked which are not
        # generated by the hypernetwork (they're maintained locally).
        self.model.head.load_state_dict(head_state, strict=False)

    def compute_loss_on_batch(
        self, signals: dict[str, torch.Tensor], labels: torch.Tensor
    ) -> torch.Tensor:
        """Compute loss on a data batch (for server-side backpropagation).

        The server calls this to get the loss that flows back through
        the generated parameters → hypernetwork → embedding network.

        Parameters:
        signals : dict[str, torch.Tensor]
            signal_name → (batch, C, T)
        labels : torch.Tensor
            (batch,) integer labels

        Returns:
        torch.Tensor
            Scalar loss (differentiable through generated parameters).
        """
        output = self.model(signals)
        return self.loss(output, labels)

    def train(self):
        """PeFLL clients do not train locally.

        All optimisation happens on the server through the hypernetwork.
        This method is to prevent the base server's train loop
        from calling local training.
        """
        pass
